import React, { useState } from 'react';
import { FaChevronDown, FaChevronUp } from 'react-icons/fa';
import Button from '../common/Button/Button';
import Input from '../common/Input/Input';
import ToggleButton from '../common/ToggleButton/ToggleButton';
import styles from './FilterSection.module.css';

const FilterSection = ({ onApplyFilters, initialFilters = {} }) => {
    const [expandedSections, setExpandedSections] = useState({
        street: true, date: true, time: true, level: true, price: true, location: true
    });

    const [filters, setFilters] = useState({
        street: initialFilters.street || '',
        date: initialFilters.date || '',
        startTime: initialFilters.startTime || '00:00',
        endTime: initialFilters.endTime || '23:59',
        levels: initialFilters.levels || [],
        minPrice: initialFilters.minPrice || '',
        maxPrice: initialFilters.maxPrice || '',
        useNearestLocations: initialFilters.useNearestLocations || false,
        userAddress: initialFilters.userAddress || ''
    });

    const levels = ['D1', 'D2', 'D3', 'D4', 'D4Plus'];

    const toggleSection = (section) => {
        setExpandedSections({ ...expandedSections, [section]: !expandedSections[section] });
    };

    const toggleLevel = (level) => {
        if (filters.levels.includes(level)) {
            setFilters({ ...filters, levels: filters.levels.filter(l => l !== level) });
        } else {
            setFilters({ ...filters, levels: [...filters.levels, level] });
        }
    };

    const handleApply = () => onApplyFilters(filters);
    const handleClear = () => setFilters({
        street: '', date: '', startTime: '00:00', endTime: '23:59',
        levels: [], minPrice: '', maxPrice: '', useNearestLocations: false, userAddress: ''
    });

    return (
        <div className={styles.filterSection}>
            <div className={styles.filterGroup}>
                <div className={styles.filterHeader} onClick={() => toggleSection('street')}>
                    <h3 className={styles.filterTitle}>Улица</h3>
                    {expandedSections.street ? <FaChevronUp /> : <FaChevronDown />}
                </div>
                {expandedSections.street && <div className={styles.filterContent}><Input placeholder="Введите улицу" value={filters.street} onChange={(e) => setFilters({...filters, street: e.target.value})} /></div>}
            </div>

            <div className={styles.filterGroup}>
                <div className={styles.filterHeader} onClick={() => toggleSection('date')}>
                    <h3 className={styles.filterTitle}>Дата</h3>
                    {expandedSections.date ? <FaChevronUp /> : <FaChevronDown />}
                </div>
                {expandedSections.date && <div className={styles.filterContent}><input type="date" className={styles.dateInput} value={filters.date} onChange={(e) => setFilters({...filters, date: e.target.value})} /></div>}
            </div>

            <div className={styles.filterGroup}>
                <div className={styles.filterHeader} onClick={() => toggleSection('time')}>
                    <h3 className={styles.filterTitle}>Время</h3>
                    {expandedSections.time ? <FaChevronUp /> : <FaChevronDown />}
                </div>
                {expandedSections.time && (
                    <div className={styles.filterContent}>
                        <div className={styles.timeRange}>
                            <input type="time" className={styles.timeInput} value={filters.startTime} onChange={(e) => setFilters({...filters, startTime: e.target.value})} />
                            <span className={styles.timeSeparator}>-</span>
                            <input type="time" className={styles.timeInput} value={filters.endTime} onChange={(e) => setFilters({...filters, endTime: e.target.value})} />
                        </div>
                    </div>
                )}
            </div>

            <div className={styles.filterGroup}>
                <div className={styles.filterHeader} onClick={() => toggleSection('level')}>
                    <h3 className={styles.filterTitle}>Уровень игры</h3>
                    {expandedSections.level ? <FaChevronUp /> : <FaChevronDown />}
                </div>
                {expandedSections.level && (
                    <div className={styles.filterContent}>
                        <div className={styles.levelButtons}>
                            {levels.map(level => (<ToggleButton key={level} label={level === 'D4Plus' ? 'D4+' : level} isActive={filters.levels.includes(level)} onClick={() => toggleLevel(level)} />))}
                        </div>
                    </div>
                )}
            </div>

            <div className={styles.filterGroup}>
                <div className={styles.filterHeader} onClick={() => toggleSection('price')}>
                    <h3 className={styles.filterTitle}>Стоимость</h3>
                    {expandedSections.price ? <FaChevronUp /> : <FaChevronDown />}
                </div>
                {expandedSections.price && (
                    <div className={styles.filterContent}>
                        <div className={styles.priceRange}>
                            <input type="number" className={styles.priceInput} placeholder="От" value={filters.minPrice} onChange={(e) => setFilters({...filters, minPrice: e.target.value})} />
                            <span className={styles.priceSeparator}>-</span>
                            <input type="number" className={styles.priceInput} placeholder="До" value={filters.maxPrice} onChange={(e) => setFilters({...filters, maxPrice: e.target.value})} />
                        </div>
                    </div>
                )}
            </div>

            <div className={styles.filterGroup}>
                <div className={styles.filterHeader} onClick={() => toggleSection('location')}>
                    <h3 className={styles.filterTitle}>Расположение площадки</h3>
                    {expandedSections.location ? <FaChevronUp /> : <FaChevronDown />}
                </div>
                {expandedSections.location && (
                    <div className={styles.filterContent}>
                        <ToggleButton label="Ближайшие площадки" isActive={filters.useNearestLocations} onClick={() => setFilters({...filters, useNearestLocations: !filters.useNearestLocations})} />
                        {filters.useNearestLocations && (<Input placeholder="Ваш адрес" value={filters.userAddress} onChange={(e) => setFilters({...filters, userAddress: e.target.value})} style={{ marginTop: '1rem' }} />)}
                    </div>
                )}
            </div>

            <div className={styles.filterActions}>
                <Button variant="outline" size="small" onClick={handleClear}>Очистить всё</Button>
                <Button size="small" onClick={handleApply}>Применить</Button>
            </div>
        </div>
    );
};

export default FilterSection;
